import{_ as a}from"./chunks/more.BA9dr6o4.js";import{_ as r,c as s,o as t,a2 as o}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse(`{"title":"D'autres façons de comparer","description":"Comparez des images et des archives, exportez une comparaison en image, et ajustez l'apparence et la langue.","frontmatter":{"title":"D'autres façons de comparer","description":"Comparez des images et des archives, exportez une comparaison en image, et ajustez l'apparence et la langue."},"headers":[],"relativePath":"fr/guide/more.md","filePath":"fr/guide/more.md","lastUpdated":1794296122000}`),i={name:"fr/guide/more.md"};function n(u,e,c,l,p,m){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="d-autres-facons-de-comparer" tabindex="-1">D&#39;autres façons de comparer <a class="header-anchor" href="#d-autres-facons-de-comparer" aria-label="Permalink to &quot;D&#39;autres façons de comparer&quot;">​</a></h1><p>Le texte n&#39;est qu&#39;une partie de l&#39;histoire. qDiff ouvre plusieurs autres types de contenu selon le même principe de comparaison côte à côte.</p><img src="'+a+'" alt="Deux images comparées côte à côte" class="guide-shot"><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Placez deux images côte à côte pour les comparer confortablement, ou superposez-les pour voir exactement où elles diffèrent — pratique pour les révisions de maquettes et les photos presque identiques.</p><h2 id="archives-compressees" tabindex="-1">Archives compressées <a class="header-anchor" href="#archives-compressees" aria-label="Permalink to &quot;Archives compressées&quot;">​</a></h2><p>Une archive .zip ou .tar peut être ouverte directement et comparée comme un dossier. Aucune décompression, aucun fichier temporaire à nettoyer ensuite.</p><h2 id="les-fichiers-qui-ne-sont-pas-du-texte-brut" tabindex="-1">Les fichiers qui ne sont pas du texte brut <a class="header-anchor" href="#les-fichiers-qui-ne-sont-pas-du-texte-brut" aria-label="Permalink to &quot;Les fichiers qui ne sont pas du texte brut&quot;">​</a></h2><p>Quand deux fichiers se ressemblent mais se comportent différemment, qDiff peut les comparer jusque dans les moindres détails, y compris des différences qu&#39;une vue texte ne peut pas montrer.</p><h2 id="enregistrer-une-comparaison-en-image" tabindex="-1">Enregistrer une comparaison en image <a class="header-anchor" href="#enregistrer-une-comparaison-en-image" aria-label="Permalink to &quot;Enregistrer une comparaison en image&quot;">​</a></h2><p>Sélectionnez une modification et exportez-la en image nette sur deux colonnes — prête à coller dans un message, un document ou une revue. L&#39;image ne comporte aucune marque ajoutée.</p><h2 id="faites-le-votre" tabindex="-1">Faites-le vôtre <a class="header-anchor" href="#faites-le-votre" aria-label="Permalink to &quot;Faites-le vôtre&quot;">​</a></h2><ul><li><strong>Apparence</strong> — claire et sombre, en suivant votre Mac ou réglée à la main.</li><li><strong>Langue</strong> — anglais, chinois simplifié, chinois traditionnel, japonais, allemand, espagnol et français.</li><li><strong>Polices et raccourcis</strong> — ajustez le confort de lecture et utilisez le clavier pour les actions que vous répétez le plus.</li><li><strong>Comparaisons récentes</strong> — rouvrez depuis l&#39;écran d&#39;accueil un élément consulté la veille.</li></ul><p>Tout ce qui précède est inclus dans la version gratuite.</p><p>Une question ? <a href="./faq.html">Consultez la FAQ</a>.</p>',15)])])}const g=r(i,[["render",n]]);export{f as __pageData,g as default};
